// ══════════════════════════════════════════════════
// НОВЫЙ КОД: Определение юридического документа
// ══════════════════════════════════════════════════

const fileName = ($('получаем данные о файлах').item.json.name || '').toLowerCase();
const fileType = $('получаем данные о файлах').item.json.type;

// Получаем результат OCR
const ocrResult = $('Отправить в Google Script').item.json || '';
const scannedText = typeof ocrResult === 'string' ? ocrResult : (ocrResult.data || ocrResult.text || '');

// Ключевые слова юридических документов (русский + английский + казахский)
const legalKeywords = [
  // Русский
  'договор', 'соглашение', 'контракт', 'нда',
  'аренда', 'найм', 'услуг', 'подряд',
  'трудов', 'купли', 'продаж', 'поставк',
  'займ', 'кредит', 'залог', 'поручительств',
  // Английский
  'contract', 'agreement', 'nda', 'lease',
  'rental', 'service', 'employment', 'purchase',
  'sale', 'loan', 'pledge',
  // Казахский
  'келісімшарт', 'шарт', 'жалға', 'қызмет',
  // Юридические термины
  'сторона', 'обязуется', 'вправе',
  'ответственность', 'арендатор', 'арендодатель',
  'заказчик', 'исполнитель', 'работник', 'работодатель'
];

// Проверка по имени файла
const isLegalByName = legalKeywords.some(kw => fileName.includes(kw));

// Проверка по содержимому (первые 500 символов)
const textSample = scannedText.toLowerCase().substring(0, 500);
const keywordMatches = legalKeywords.filter(kw => textSample.includes(kw)).length;
const isLegalByContent = keywordMatches >= 3; // Минимум 3 совпадения

// Проверка формата файла
const isPdfOrDocx = fileType === 'pdf' || 
                    fileType === 'document' || 
                    fileName.match(/\.(pdf|docx?|doc)$/);

// Проверка размера текста (минимум 200 символов для анализа)
const hasEnoughText = scannedText.length >= 200;

// Финальное решение
const isLegalDocument = (isLegalByName || isLegalByContent) && 
                        isPdfOrDocx && 
                        hasEnoughText;

console.log('Legal document detection:', {
  fileName,
  isLegalByName,
  isLegalByContent,
  keywordMatches,
  isPdfOrDocx,
  textLength: scannedText.length,
  FINAL: isLegalDocument
});

return [{
  json: {
    isLegalDocument: isLegalDocument,
    shouldAnalyze: isLegalDocument,
    fileName: fileName,
    fileType: fileType,
    scannedText: scannedText,
    textLength: scannedText.length,
    detectionReason: isLegalByName ? 'filename' : isLegalByContent ? 'content' : 'none',
    keywordMatches: keywordMatches
  }
}];

// ══════════════════════════════════════════════════
// ПОДГОТОВКА ДАННЫХ ДЛЯ ЮРИДИЧЕСКОГО АНАЛИЗА
// ══════════════════════════════════════════════════

const chatId = $('получаем данные о файлах').item.json.chatId;
const messageIds = $('получаем данные о файлах').item.json.allMessageIds;
const documentText = $('🔍 Detect Legal Document').item.json.scannedText;
const fileName = $('🔍 Detect Legal Document').item.json.fileName;

// Валидация текста
if (!documentText || documentText.trim().length < 200) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: '⚠️ *Не удалось извлечь текст*\n\nФайл слишком мал или плохо распознался.\n\n💡 Попробуйте:\n• Загрузить файл лучшего качества\n• Проверить, что файл не зашифрован\n• Использовать PDF вместо скана'
    }
  }];
}

return [{
  json: {
    chatId: chatId,
    messageIds: messageIds,
    documentText: documentText,
    fileName: fileName,
    textLength: documentText.length,
    estimatedPages: Math.ceil(documentText.length / 3000) // примерно 3000 символов на страницу
  }
}];

const remaining = $('💳 Check Limits').item.json.remaining_analyses || 0;
const tier = $('💳 Check Limits').item.json.tier || 'free';
const maxPages = $('💳 Check Limits').item.json.max_pages || 3;
const docPages = $('📄 Prepare Document').item.json.estimatedPages;
const hasLimit = $('💳 Check Limits').item.json.can_analyze;
const chatId = $('📄 Prepare Document').item.json.chatId;

let message = '';

// Случай 1: Нет лимита
if (!hasLimit) {
  message = `❌ *Лимит исчерпан*\n\n`;

  if (tier === 'free') {
    message += `Вы использовали свой *бесплатный анализ* за этот месяц.\n\n`;
    message += `💎 *Доступные пакеты:*\n`;
    message += `📦 5 анализов - 2990 ₸\n`;
    message += `📦 10 анализов - 4990 ₸ _(выгода 1000₸)_\n`;
    message += `👑 20 анализов - 7990 ₸ _(выгода 3990₸)_\n\n`;
  } else {
    message += `Анализы в вашем пакете закончились.\n\n`;
    message += `Для продолжения работы приобретите дополнительный пакет.\n\n`;
  }

  message += `💳 Купить: /pay\n`;
  message += `📊 Баланс: /balance`;
}
// Случай 2: Документ слишком большой
else if (docPages > maxPages) {
  message = `📏 *Документ слишком большой*\n\n`;
  message += `Ваш документ: *~${docPages} страниц*\n`;
  message += `Лимит тарифа *${tier}*: ${maxPages} страниц\n\n`;

  if (tier === 'free') {
    message += `💡 *Решения:*\n`;
    message += `1. Купить пакет (до 10-15 стр)\n`;
    message += `2. Отправить первые ${maxPages} страницы\n\n`;
    message += `Купить пакет: /pay`;
  } else {
    message += `Для анализа больших документов (до 15 стр) нужен 👑 *Premium*\n\n`;
    message += `Подробнее: /premium`;
  }
}

return [{
  json: {
    chatId: chatId,
    message: message,
    stopProcessing: true,
    sourceType: 'limit_exceeded'
  }
}];

// ══════════════════════════════════════════════════
// ПОДГОТОВКА КОНТЕКСТА ДЛЯ ВЕКТОРНОГО ПОИСКА
// ══════════════════════════════════════════════════

const docText = $('📄 Prepare Document').item.json.documentText;

// Берем первые 2000 символов для создания поискового запроса
// (ключевые термины обычно в начале)
const queryText = docText.substring(0, 2000);

// Извлекаем ключевые термины для улучшения поиска
const keywords = [];

// Типы договоров
if (queryText.match(/аренд/i)) keywords.push('аренда');
if (queryText.match(/услуг/i)) keywords.push('услуги');
if (queryText.match(/нда|неразглашен/i)) keywords.push('конфиденциальность');
if (queryText.match(/труд|работ/i)) keywords.push('труд');

// Ключевые аспекты
if (queryText.match(/штраф|пен|неустой/i)) keywords.push('штрафы');
if (queryText.match(/расторж|отказ/i)) keywords.push('расторжение');
if (queryText.match(/ответственн/i)) keywords.push('ответственность');

const enrichedQuery = keywords.length > 0 
  ? `${keywords.join(' ')} ${queryText}`
  : queryText;

return [{
  json: {
    queryText: enrichedQuery,
    extractedKeywords: keywords
  }
}];

// Форматируем найденный юридический контекст
const legalDocs = $input.all();

if (legalDocs.length === 0) {
  return [{
    json: {
      legalContext: 'Релевантный контекст из законов РК не найден. Анализ будет основан на общих принципах права.',
      contextsFound: 0
    }
  }];
}

// Группируем по категориям для лучшей структуры
const grouped = {};
legalDocs.forEach(doc => {
  const category = doc.json.category || 'other';
  if (!grouped[category]) {
    grouped[category] = [];
  }
  grouped[category].push(doc.json);
});

// Формируем контекст
let contextText = '═══ РЕЛЕВАНТНЫЙ ЮРИДИЧЕСКИЙ КОНТЕКСТ ═══\n\n';

for (const [category, docs] of Object.entries(grouped)) {
  const categoryNames = {
    'civil_code': '📕 ГРАЖДАНСКИЙ КОДЕКС РК',
    'labor_code': '📗 ТРУДОВОЙ КОДЕКС РК',
    'judicial_practice': '⚖️ СУДЕБНАЯ ПРАКТИКА',
    'contract_templates': '📋 ТИПОВЫЕ ФОРМЫ ДОГОВОРОВ'
  };

  contextText += `\n${categoryNames[category] || category.toUpperCase()}:\n`;
  contextText += `${'─'.repeat(50)}\n\n`;

  docs.forEach((doc, idx) => {
    contextText += `${idx + 1}. ${doc.title || 'Без названия'}\n`;
    contextText += `   Релевантность: ${(doc.similarity * 100).toFixed(1)}%\n`;
    contextText += `   ${doc.content.substring(0, 500)}...\n\n`;
  });
}

contextText += `\n${'═'.repeat(50)}\n`;
contextText += `Всего найдено релевантных источников: ${legalDocs.length}\n`;

return [{
  json: {
    legalContext: contextText,
    contextsFound: legalDocs.length,
    categories: Object.keys(grouped)
  }
}];

