// ══════════════════════════════════════════════════
// ФОРМАТИРОВАНИЕ ОТВЕТА ПОЛЬЗОВАТЕЛЮ
// ══════════════════════════════════════════════════

let analysisResult;
try {
  const aiResponse = $json.message || $json.text || $json.content || '';

  // Пытаемся извлечь JSON
  const jsonMatch = aiResponse.match(/```json\s*([\s\S]*?)\s*```/) || 
                   aiResponse.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    const jsonText = jsonMatch[1] || jsonMatch[0];
    analysisResult = JSON.parse(jsonText);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  console.error('JSON parse error:', e);
  analysisResult = {
    document_type: 'unknown',
    overall_risk_score: 3,
    risk_points: [],
    executive_summary: $json.message || 'Ошибка анализа'
  };
}

const chatId = $('📄 Prepare Document').item.json.chatId;
const fileName = $('📄 Prepare Document').item.json.fileName;
const riskScore = analysisResult.overall_risk_score || 3;

// ══════════════════════════════════════════════════
// ФОРМИРУЕМ СООБЩЕНИЕ
// ══════════════════════════════════════════════════

let msg = `⚖️ *ЮРИДИЧЕСКИЙ АНАЛИЗ ЗАВЕРШЕН*\n\n`;
msg += `📄 Файл: _${fileName}_\n`;
msg += `📊 Тип: ${analysisResult.document_type?.replace('_', ' ') || 'не определен'}\n\n`;

// Общая оценка с эмодзи
const riskEmojis = {
  1: '✅ Минимальный',
  2: '✅ Низкий',
  3: '⚠️ Средний',
  4: '🚨 Высокий',
  5: '🔴 КРИТИЧЕСКИЙ'
};

msg += `*ОБЩИЙ УРОВЕНЬ РИСКА:* ${riskEmojis[riskScore] || '⚠️'} (${riskScore}/5)\n\n`;

// Детализация по категориям (если есть)
if (analysisResult.risk_breakdown) {
  msg += `*Детализация:*\n`;
  const rb = analysisResult.risk_breakdown;
  msg += `├ Финансовые: ${rb.financial || '-'}/5\n`;
  msg += `├ Расторжение: ${rb.termination || '-'}/5\n`;
  msg += `├ Ответственность: ${rb.liability || '-'}/5\n`;
  msg += `├ Процедурные: ${rb.procedural || '-'}/5\n`;
  msg += `└ Правовые дефекты: ${rb.legal || '-'}/5\n\n`;
}

// Executive Summary
if (analysisResult.executive_summary) {
  msg += `*📌 РЕЗЮМЕ:*\n${analysisResult.executive_summary}\n\n`;
}

// Критические риски (4-5 баллов)
const criticalRisks = (analysisResult.risk_points || []).filter(r => r.risk_level >= 4);
if (criticalRisks.length > 0) {
  msg += `*🚨 КРИТИЧЕСКИЕ РИСКИ:*\n\n`;
  criticalRisks.forEach((risk, idx) => {
    msg += `${idx + 1}. *${risk.issue}*\n`;
    msg += `   📍 Пункт: ${risk.clause_number || 'не указан'}\n`;
    if (risk.legal_reference) {
      msg += `   ⚖️ Закон: ${risk.legal_reference}\n`;
    }
    msg += `   💡 ${risk.recommendation}\n\n`;
  });
}

// Средние риски (3 балла)
const mediumRisks = (analysisResult.risk_points || []).filter(r => r.risk_level === 3);
if (mediumRisks.length > 0) {
  msg += `*⚠️ ТРЕБУЮТ ВНИМАНИЯ (${mediumRisks.length}):*\n`;
  mediumRisks.slice(0, 3).forEach((risk, idx) => {
    msg += `• ${risk.issue}\n`;
  });
  if (mediumRisks.length > 3) {
    msg += `  _...и еще ${mediumRisks.length - 3}_\n`;
  }
  msg += `\n`;
}

// Положительные моменты
if (analysisResult.positive_points && analysisResult.positive_points.length > 0) {
  msg += `*✅ ПОЛОЖИТЕЛЬНЫЕ МОМЕНТЫ:*\n`;
  analysisResult.positive_points.slice(0, 3).forEach(point => {
    msg += `• ${point}\n`;
  });
  msg += `\n`;
}

// Отсутствующие пункты
if (analysisResult.missing_clauses && analysisResult.missing_clauses.length > 0) {
  const critical = analysisResult.missing_clauses.filter(c => c.importance === 'critical');
  if (critical.length > 0) {
    msg += `*📋 ОТСУТСТВУЮТ ВАЖНЫЕ ПУНКТЫ:*\n`;
    critical.forEach(clause => {
      msg += `• ${clause.clause_name}\n`;
      msg += `  ${clause.why_needed}\n`;
    });
    msg += `\n`;
  }
}

// План действий
if (analysisResult.action_items && analysisResult.action_items.length > 0) {
  msg += `*🎯 ПЛАН ДЕЙСТВИЙ:*\n\n`;

  const urgent = analysisResult.action_items.filter(a => a.priority === 'urgent');
  const high = analysisResult.action_items.filter(a => a.priority === 'high');

  if (urgent.length > 0) {
    msg += `⚡ СРОЧНО:\n`;
    urgent.forEach(action => {
      msg += `  ${action.action}\n`;
    });
    msg += `\n`;
  }

  if (high.length > 0) {
    msg += `📌 ВАЖНО:\n`;
    high.forEach(action => {
      msg += `  ${action.action}\n`;
    });
    msg += `\n`;
  }
}

// Вердикт
let verdict = '';
if (riskScore <= 2) {
  verdict = '✅ *ВЕРДИКТ:* Можно подписывать';
} else if (riskScore === 3) {
  verdict = '⚠️ *ВЕРДИКТ:* Рекомендуется внести правки';
} else if (riskScore === 4) {
  verdict = '🚨 *ВЕРДИКТ:* Требуются обязательные правки';
} else {
  verdict = '🔴 *ВЕРДИКТ:* НЕ ПОДПИСЫВАТЬ в текущей редакции';
}

msg += verdict + `\n\n`;

// Премиум функции
const tier = $('💳 Check Limits').item.json.tier;
if (tier !== 'premium') {
  msg += `\n━━━━━━━━━━━━━━━━━\n`;
  msg += `💎 *PREMIUM ФУНКЦИИ:*\n`;
  msg += `• Протокол разногласий\n`;
  msg += `• Сравнение версий\n`;
  msg += `• Расширенный анализ\n`;
  msg += `Подробнее: /premium\n\n`;
}

// Обязательный disclaimer
msg += `\n⚖️ _Данный анализ носит информационный характер и не является юридической консультацией. Для принятия важных решений обратитесь к квалифицированному юристу._\n\n`;
msg += `❓ Вопросы: /help | 💳 Баланс: /balance`;

return [{
  json: {
    chatId: chatId,
    message: msg,
    analysisResult: analysisResult,
    riskScore: riskScore,
    sourceType: 'legal_analysis',
    processed_message_ids: $('📄 Prepare Document').item.json.messageIds
  }
}];
